<section class="section-card"><h2>{{ $manager?'Team attendance':'My attendance' }}</h2>@foreach($attendance as $entry)@php($endTime=$entry->effective_out_at??$entry->clocked_out_at)@php($startTime=$entry->effective_in_at??$entry->clocked_in_at)<details class="sticker-panel" style="margin-bottom:14px"><summary>{{ $entry->person?->name??$entry->user?->name }} · {{ $entry->approved_at?'Approved':'Needs review' }} · {{ $startTime->timezone('Africa/Kampala')->format('d M H:i') }} EAT</summary><p>Observed arrival {{ $entry->clocked_in_at->timezone('Africa/Kampala')->format('d M H:i') }} · Observed departure {{ $entry->clocked_out_at?->timezone('Africa/Kampala')->format('d M H:i')??'MISSING / open' }}</p><p>Effective interval {{ $startTime->timezone('Africa/Kampala')->format('d M H:i') }}–{{ $endTime?->timezone('Africa/Kampala')->format('d M H:i')??'unresolved' }} EAT. @if($endTime)Elapsed {{ (int)$startTime->diffInMinutes($endTime) }} minutes before breaks.@endif</p>@if($entry->shift&&$startTime->gt($entry->shift->starts_at))<p class="platform-warning">Arrival after planned shift start: {{ (int)$entry->shift->starts_at->diffInMinutes($startTime) }} minutes. Review the evidence; no pay deduction is automatic.</p>@endif
