@if(!$entry->clocked_out_at&&$entry->user_id===auth()->id())<form method="POST" action="{{ route('people.break',$entry) }}">@csrf<input name="action" type="hidden" value="{{ $breaks->get($entry->id,collect())->whereNull('ends_at')->isNotEmpty()?'end':'start' }}"><button class="secondary-button">{{ $breaks->get($entry->id,collect())->whereNull('ends_at')->isNotEmpty()?'End break':'Start break' }}</button></form>@endif
